const fs = require('fs');

const DEVICE = '43a8770c1717da93ef8835f946aba0a0d069b2f7';
const URL = `ws://127.0.0.1:8081/inspector/debug?device=${DEVICE}&page=1`;
const LOG = '/tmp/heals-monitor/js.log';

const out = fs.createWriteStream(LOG, { flags: 'a' });

const write = (line) => {
  const text = `[${new Date().toISOString()}] ${line}\n`;
  out.write(text);
  process.stdout.write(text);
};

const preview = (value, limit = 12000) => {
  const text = typeof value === 'string' ? value : JSON.stringify(value);
  if (!text) {
    return '';
  }
  return text.length > limit ? `${text.slice(0, limit)}...[truncated ${text.length}]` : text;
};

const argText = (arg) => {
  if (!arg) {
    return '';
  }
  if (typeof arg.value !== 'undefined') {
    return preview(arg.value);
  }
  if (arg.unserializableValue) {
    return String(arg.unserializableValue);
  }
  if (arg.description) {
    return preview(arg.description);
  }
  if (arg.preview) {
    return preview(arg.preview);
  }
  return preview(arg);
};

let ws;
let reconnectTimer;
let nextId = 1;

const send = (method, params) => {
  if (!ws || ws.readyState !== WebSocket.OPEN) {
    return;
  }
  const id = nextId;
  nextId += 1;
  ws.send(JSON.stringify({ id, method, params }));
};

const connect = () => {
  write(`CONNECT ${URL}`);
  ws = new WebSocket(URL);
  ws.on('open', () => {
    write('OPEN');
    send('Runtime.enable');
    send('Console.enable');
    send('Log.enable');
    setTimeout(() => {
      send('Runtime.evaluate', {
        expression: 'console.log("[heals-monitor] cdp-ready")',
        returnByValue: true,
      });
    }, 400);
  });
  ws.on('message', (data) => {
    let msg;
    try {
      msg = JSON.parse(data.toString());
    } catch (error) {
      write(`RAW ${preview(data.toString())}`);
      return;
    }
    if (msg.method === 'Runtime.consoleAPICalled') {
      const args = (msg.params?.args || []).map(argText).join(' ');
      write(`CONSOLE ${msg.params?.type || 'log'} ${args}`);
      return;
    }
    if (msg.method === 'Log.entryAdded') {
      write(`LOG ${preview(msg.params?.entry)}`);
      return;
    }
    if (msg.method === 'Console.messageAdded') {
      write(`CONSOLE_MSG ${preview(msg.params?.message)}`);
      return;
    }
    if (msg.id && msg.error) {
      write(`RPC_ERROR ${preview(msg)}`);
      return;
    }
    if (msg.method && !String(msg.method).startsWith('Debugger.')) {
      write(`EVENT ${msg.method}`);
    }
  });
  ws.on('close', (code, reason) => {
    write(`CDP_CLOSE ${code} ${reason ? reason.toString() : ''}`);
    scheduleReconnect();
  });
  ws.on('error', (error) => {
    write(`CDP_ERROR ${error.message}`);
  });
};

const scheduleReconnect = () => {
  if (reconnectTimer) {
    return;
  }
  reconnectTimer = setTimeout(() => {
    reconnectTimer = null;
    connect();
  }, 1000);
};

connect();

const WebSocket = require('/Users/stark/Desktop/work/RN/heals-app-rn/node_modules/ws');
const fs = require('fs');

const DEVICE = '43a8770c1717da93ef8835f946aba0a0d069b2f7';
const URL = `ws://127.0.0.1:8081/inspector/debug?device=${DEVICE}&page=1`;
const LOG = '/tmp/heals-monitor/js.log';

const out = fs.createWriteStream(LOG, { flags: 'a' });
const pending = new Map();

let ws = null;
let live = false;
let sessionToken = '';
let reconnectTimer = null;
let nextId = 1;
let closingSelf = false;

const write = (line, toStdout = true) => {
  const text = `[${new Date().toISOString()}] ${line}\n`;
  out.write(text);
  if (toStdout) {
    process.stdout.write(text);
  }
};

const preview = (value, limit = 8000) => {
  const text = typeof value === 'string' ? value : JSON.stringify(value);
  if (!text) {
    return '';
  }
  return text.length > limit ? `${text.slice(0, limit)}...[truncated ${text.length}]` : text;
};

const argText = (arg) => {
  if (!arg) {
    return '';
  }
  if (Object.prototype.hasOwnProperty.call(arg, 'value')) {
    return preview(arg.value);
  }
  if (arg.unserializableValue) {
    return String(arg.unserializableValue);
  }
  if (arg.preview && Array.isArray(arg.preview.properties)) {
    const pairs = arg.preview.properties.slice(0, 20).map((prop) => {
      const value = prop.value !== undefined ? prop.value : prop.description || prop.type;
      return `${prop.name}=${preview(value, 300)}`;
    });
    return `{${pairs.join(', ')}}`;
  }
  if (arg.description && arg.description !== 'Object' && arg.description !== 'Array') {
    return preview(arg.description);
  }
  return arg.type || '';
};

const send = (method, params) => {
  if (!ws || ws.readyState !== WebSocket.OPEN) {
    return 0;
  }
  const id = nextId;
  nextId += 1;
  ws.send(JSON.stringify({ id, method, params }));
  return id;
};

const stringifyRemote = (objectId) => {
  const id = send('Runtime.callFunctionOn', {
    objectId,
    returnByValue: true,
    functionDeclaration: `function() {
      const secret = /authorization|token|secret|password|cookie/i;
      const seen = new WeakSet();
      const trim = (value, depth) => {
        if (value == null) return value;
        const kind = typeof value;
        if (kind === 'string') {
          return value.length > 1500 ? value.slice(0, 1500) + '...[truncated]' : value;
        }
        if (kind !== 'object') return value;
        if (seen.has(value) || depth > 4) return Array.isArray(value) ? '[Array]' : '[Object]';
        seen.add(value);
        if (Array.isArray(value)) return value.slice(0, 20).map((item) => trim(item, depth + 1));
        const output = {};
        Object.keys(value).slice(0, 30).forEach((key) => {
          output[key] = secret.test(key) ? '[redacted]' : trim(value[key], depth + 1);
        });
        return output;
      };
      try { return JSON.stringify(trim(this, 0)); }
      catch (error) { return 'stringify-failed:' + error.message; }
    }`,
  });
  if (id) {
    pending.set(id, true);
  }
};

const connect = () => {
  if (ws && (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING)) {
    return;
  }
  live = false;
  sessionToken = `cdp-live-${Date.now()}`;
  write(`CONNECT ${sessionToken}`, false);
  const socket = new WebSocket(URL);
  ws = socket;
  socket.on('open', () => {
    if (ws !== socket) {
      return;
    }
    write('OPEN', false);
    send('Runtime.enable');
    send('Log.enable');
    setTimeout(() => {
      if (ws !== socket) {
        return;
      }
      send('Runtime.evaluate', {
        expression: `console.log("${sessionToken}")`,
        returnByValue: true,
      });
    }, 300);
  });
  socket.on('message', (data) => {
    if (ws !== socket) {
      return;
    }
    let msg;
    try {
      msg = JSON.parse(data.toString());
    } catch (error) {
      return;
    }
    if (msg.id && pending.has(msg.id)) {
      pending.delete(msg.id);
      if (!live) {
        return;
      }
      const value = msg.result?.result?.value || msg.result?.result?.description || msg.error?.message;
      write(`OBJECT ${preview(value)}`);
      return;
    }
    if (msg.method === 'Runtime.consoleAPICalled') {
      const args = msg.params?.args || [];
      const text = args.map(argText).join(' ');
      if (!live) {
        if (text.includes(sessionToken)) {
          live = true;
          write(`LIVE ${sessionToken}`);
        }
        return;
      }
      write(`CONSOLE ${msg.params?.type || 'log'} ${text}`);
      args.forEach((arg) => {
        if (arg && arg.objectId && arg.type === 'object') {
          stringifyRemote(arg.objectId);
        }
      });
      return;
    }
    if (!live) {
      return;
    }
    if (msg.method === 'Log.entryAdded') {
      write(`LOG ${preview(msg.params?.entry?.text || msg.params?.entry)}`);
    }
  });
  socket.on('close', (code, reason) => {
    if (ws !== socket) {
      return;
    }
    ws = null;
    live = false;
    const why = reason ? reason.toString() : '';
    write(`CDP_CLOSE ${code} ${why}`);
    if (!closingSelf) {
      scheduleReconnect();
    }
  });
  socket.on('error', (error) => {
    if (ws !== socket) {
      return;
    }
    write(`CDP_ERROR ${error.message}`);
  });
};

const scheduleReconnect = () => {
  if (reconnectTimer) {
    return;
  }
  reconnectTimer = setTimeout(() => {
    reconnectTimer = null;
    connect();
  }, 1500);
};

connect();
